head.script:
// [FAIL] gridView accessibility="true" / sortable="true" 인 경우
//        정렬 가능한 Header 의 "button.w2grid_head_sort_div_main_btn_accessibility" 로
//        Tab 키 포커스 이동이 가능해야 하는데, 그리드 시작 영역에서 Tab 을 누르면
//        Header 정렬 button 을 모두 건너뛰고 첫번째 Body Cell 입력창으로 포커스가 이동한다.

scwin.onpageload = function () {
    // 포커스 이동 경로를 결과창에 순서대로 출력한다.
    document.addEventListener('focusin', scwin.onAnyFocusIn, true);
};



// Tab 으로 포커스가 도착한 그리드 요소만 순서대로 출력
scwin.onAnyFocusIn = function (e) {
    let name = scwin.describe(e.target);
    if (!name) {
        return;
    }
    scwin.step = (scwin.step || 0) + 1;
    scwin.setReturnValue(scwin.step + ". " + name);
};



// 포커스된 그리드 요소 이름 (그리드 밖 요소는 출력하지 않음)
scwin.describe = function (el) {
    if (!el) {
        return "";
    }
    let cls = (el.className || "").toString();
    if (cls.indexOf("w2grid_head_sort_div_main_btn_accessibility") >= 0) {
        return "Header 정렬 button";
    }
    if (cls.indexOf("w2grid_start_div") >= 0) {
        return "그리드 시작 영역";
    }
    if (cls.indexOf("w2grid_end_div") >= 0) {
        return "그리드 끝 영역";
    }
    let td = el;
    while (td && td.tagName !== "TD") {
        td = td.parentNode;
    }
    let m = (td && td.id ? td.id : "").match(/_cell_(\d+)_(\d+)/);
    if (m) {
        return "Body Cell (" + (Number(m[1]) + 1) + "행, col" + (Number(m[2]) + 1) + ")";
    }
    return "";
};



// Header 정렬 button 에서 Space/Enter 를 누르면 발생
scwin.grid_bug_onsort = function (sortInfo) {
    scwin.setReturnValue("정렬 발생 : sortOrder=" + sortInfo.sortOrder);
};



// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    scwin.step = 0;
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
